local config = {
  ui_story_30110401_1_dialog_content = "<color=#e8d9bb>... 1, 2, 3, 4...</color>",
  ui_story_30110401_2_dialog_content = "<color=#e8d9bb>Hablando de eso, podría haber olvidado algo importante...</color>",
  ui_story_30110401_3_dialog_content = "¿Por qué estás distraído? ¿Escuchaste mi pregunta?",
  ui_story_30110401_4_dialog_content = "Entonces permíteme reiterar: Por favor, explícame cómo no estás durmiendo bien.",
  ui_story_30110401_5_option_content = "Lo siento, señora. Me asustó.",
  ui_story_30110401_6_dialog_content = "No quise ofender. Por favor, intenta acostumbrarte.",
  ui_story_30110401_7_dialog_content = "Te pedí que me lo resumieras porque es difícil para mí tomar alguna acción antes de saber más sobre tu situación.",
  ui_story_30110401_8_option_content = "Lo siento. Estaba atrapado en mis pensamientos.",
  ui_story_30110401_9_dialog_content = "Probablemente no me expliqué bien. Esperaba que pudieras darme un breve resumen de tu situación.",
  ui_story_30110401_10_dialog_content = "Una vez que entienda, podré seleccionar una solución más apropiada.",
  ui_story_30110401_11_dialog_content = "Bueno, he estado teniendo problemas para conciliar el sueño y levantarme, sintiéndome aturdido y cansado todo el tiempo.",
  ui_story_30110401_12_dialog_content = "Pero, ¿por qué le importa esto, señora?",
  ui_story_30110401_13_dialog_content = "... ¿Y parece que estás decidido a ayudarme a resolverlo?",
  ui_story_30110401_14_dialog_content = "Primero, esto no es lo único para lo que te pedí que vinieras a tratar. Tengo mis consideraciones.",
  ui_story_30110401_15_dialog_content = "Solo haz lo que digo. No hay necesidad de preocuparte.",
  ui_story_30110401_16_dialog_content = "En segundo lugar, los soldados en las legiones que entrené a menudo tenían problemas similares a los tuyos.",
  ui_story_30110401_17_dialog_content = "Dado que tengo experiencia en tratar con ellos, ayudarte no me supone ningún esfuerzo.",
  ui_story_30110401_18_option_content = "Parece que acabas de deshacerte de los soldados problemáticos...",
  ui_story_30110401_19_dialog_content = "No, por supuesto, me deshice de sus problemas de sueño.",
  ui_story_30110401_20_dialog_content = "No te preocupes. Solo el 10 por ciento de lo que eliminé eran los soldados problemáticos.",
  ui_story_30110401_21_dialog_content = "No estoy entre ese 10 por ciento, ¿verdad...",
  ui_story_30110401_22_option_content = "Impresionante. Entonces, ¿solo hago lo que dices, verdad?",
  ui_story_30110401_23_dialog_content = "Por supuesto que no. Sé por experiencia que este método puede sacar eficazmente el potencial del cuerpo humano.",
  ui_story_30110401_24_dialog_content = "Mejorará tu salud. Te prometo que tendrás el mejor sueño.",
  ui_story_30110401_25_dialog_content = "¿Hmm? Algo no suena bien.",
  ui_story_30110401_26_dialog_content = "¿Ves esa columna de allí?",
  ui_story_30110401_27_dialog_content = "Míralo, y no te distraigas. Comienza a moverte tan pronto como dé la orden. Sin vacilación.",
  ui_story_30110401_28_dialog_content = "¡100 sentadillas! ¡Ahora!",
  ui_story_30110401_29_option_content = "¿¿¿???",
  ui_story_30110401_30_dialog_content = "Te lo dije, sin dudar. ¡Dame 50 sentadillas más! ¡Ahora!",
  ui_story_30110401_31_option_content = "¡Sí, Señora!",
  ui_story_30110401_32_dialog_content = "Reacción rápida. Bien. ¡50 más!",
  ui_story_30110401_33_dialog_content = "Corre 20 vueltas alrededor del puente. ¡Comienza!",
  ui_story_30110401_34_dialog_content = "¡Sentadillas profundas! ¡Saltos de traslado! ¡Más! ¡Aún no hemos terminado! ¡Sigue adelante!",
  ui_story_30110401_35_option_content = "No puedo más, Señora. ¿Puedo tomar un descanso?",
  ui_story_30110401_36_dialog_content = "La persistencia es victoria. Dado que he prometido prestarte más atención, debo insistir en que completes tu entrenamiento.",
  ui_story_30110401_37_option_content = "¿Cuánto queda, Señora?",
  ui_story_30110401_38_dialog_content = "No hay vuelta atrás para una flecha una vez que se ha lanzado.",
  ui_story_30110401_39_dialog_content = "¡No pienses en cuánto tiempo más va a tomar, sino en lo que vas a obtener de esto!",
  ui_story_30110401_40_dialog_content = "<color=#e8d9bb>No sé cuánto tiempo quiere el oficial Sharona que esto continúe, pero mi mente está a punto de apagarse...</color>",
  ui_story_30110401_41_dialog_content = "<color=#e8d9bb>1, 2, 3, 4...!</color>",
  ui_story_30110401_42_dialog_content = "¿Eh? ¿No es esto...",
  ui_story_30110401_43_dialog_content = "¡Mantén el ritmo! ¡Vamos, grítalo conmigo! ¡Déjame oírte! ¡1, 2, 3, 4!",
  ui_story_30110401_44_option_content = "Esto es humillante... ¡Espera un minuto, esto me suena!",
  ui_story_30110401_45_dialog_content = "Insisto en hacer ejercicios matutinos diarios, por lo que muchas personas deben haberlo recordado. Aparentemente, muchos han mostrado su interés en unirse.",
  ui_story_30110401_46_option_content = "¡Así que eras tú el que me despertaba todas las mañanas!",
  ui_story_30110401_47_dialog_content = "¿Por qué? Recibí algunas quejas, por lo que cambié la ubicación del entrenamiento al puente, que supongo que debería estar lo suficientemente lejos de la zona residencial.",
  ui_story_30110401_48_dialog_content = "Mi habitación es la más cercana al puente. Probablemente por eso siempre te escucho en mi sueño todas las mañanas.",
  ui_story_30110401_49_dialog_content = "No es de extrañar que siempre me sienta cansado cuando me despierto...",
  ui_story_30110401_50_dialog_content = "Bueno, aunque pareces reacio, aún completaste mi sesión de entrenamiento.",
  ui_story_30110401_51_dialog_content = "Y llegaste al final sin problemas. Sí tienes lo que se necesita en ti.",
  ui_story_30110401_52_dialog_content = "Dado que no puedes participar en batallas la mayoría del tiempo, no tienes muchas oportunidades para mejorar. El entrenamiento ofrece la mejor oportunidad para eso.",
  ui_story_30110401_53_dialog_content = "Además, tu evaluación de combate no debería ser del nivel más bajo.",
  ui_story_30110401_54_option_content = "¡Eres tan duro, y acabas de cambiar de tema!",
  ui_story_30110401_55_dialog_content = "Eso no es un problema. Sí prometí ocuparme de tu problema.",
  ui_story_30110401_56_dialog_content = "No estoy siendo duro sino cuidadoso.",
  ui_story_30110401_57_option_content = "Eres tan estricto, ¿y de repente me pediste que me hiciera más fuerte?",
  ui_story_30110401_58_dialog_content = "Por supuesto. No solo esperamos que te vuelvas más fuerte, también esperamos que recibas más atención.",
  ui_story_30110401_59_dialog_content = "¡Hora de descanso! Ya te has detenido, ¡pero lo permitiré! ¡No hay problema!",
  ui_story_30110401_60_dialog_content = "Deberías saber que soy muy consciente del efecto del entrenamiento.",
  ui_story_30110401_61_dialog_content = "Fue mi entrenamiento diario lo que me ayudó a convertirme en general. No te mentiría sobre esto, ¿por qué lo haría?",
  ui_story_30110401_62_dialog_content = "Creo que es porque eres especial, Señora. Normalmente nadie es promovido a general solo por entrenamiento.",
  ui_story_30110401_63_dialog_content = "Una voluntad fuerte es una necesidad para convertirse en un Comandante de la Legión. Esto también es la base sobre la cual se completa gradualmente el Rompecabezas de Poder de Illumina.",
  ui_story_30110401_64_dialog_content = "Y no olvides, tú también eres especial... El Gran Mariscal de Illumina nunca juzga mal a las personas.",
  ui_story_30110401_65_dialog_content = "Sin embargo, todavía estoy aquí para resolver tu problema.",
  ui_story_30110401_66_dialog_content = "Una buena cantidad de entrenamiento puede mejorar la calidad de tu sueño. ¡Así que mantente fuerte, mi estimado ciudadano!",
  ui_story_30110401_67_option_content = "Espera, creo que escuché algo importante...",
  ui_story_30110401_68_dialog_content = "No te preocupes. Lo entenderás todo cuando llegue el momento.",
  ui_story_30110401_69_dialog_content = "Además, no tendrás problemas para levantarte mañana.",
  ui_story_30110401_70_option_content = "Olvida el quedarte dormido. Me estoy desmayando...",
  ui_story_30110401_71_dialog_content = "Puedo ayudarte si lo necesitas ahora.",
  ui_story_30110401_72_dialog_content = "Le diré a todos que ya te has ido a descansar hoy.",
  ui_story_30110401_73_dialog_content = "¡A partir de mañana por la mañana, te sacaré de la cama en persona para entrenar!",
  ui_story_30110401_74_dialog_content = "¡Ahora, terminemos el resto de la sesión!",
  ui_story_30110401_75_dialog_content = "Todavía hay margen de mejora en tus evaluaciones...",
  ui_story_30110601_1_dialog_content = "De vuelta en Ciudad Gannon de nuevo.",
  ui_story_30110601_2_dialog_content = "Vice está haciendo su informe regular... y eso podría llevar una eternidad.",
  ui_story_30110601_3_dialog_content = "Veamos... Tal vez pueda volver al Colossus y dormir unos minutos más...",
  ui_story_30110601_4_dialog_content = "¡Esta es la tercera vez que me rechazas, camarada mío!",
  ui_story_30110601_5_dialog_content = "Así es.",
  ui_story_30110601_6_dialog_content = "El dirigible público está fuera de discusión para mí, y ni hablar de ese tren tuyo que hace temblar la tierra...",
  ui_story_30110601_7_dialog_content = "¿Hmm? Es Sharona y Charon...",
  ui_story_30110601_8_dialog_content = "Sharona parece un poco diferente cuando no está en combate...",
  ui_story_30110601_9_dialog_content = "Debería ir a saludar.",
  ui_story_30110601_10_dialog_content = "¡Ah! Eres tú, Celestita! ¡Mi querido amigo!",
  ui_story_30110601_11_dialog_content = "Ya que estás aquí, ¿te importaría ayudarme a persuadir a mi querido Comandante para que acepte un método de viaje?",
  ui_story_30110601_12_dialog_content = "La presencia del Celestita aquí no hace ninguna diferencia, Charon.",
  ui_story_30110601_13_dialog_content = "Mi respuesta sigue siendo la misma: ese tren tuyo es insoportable para viajar.",
  ui_story_30110601_14_dialog_content = "Encontraré una forma de reparar mi aeronave...",
  ui_story_30110601_15_dialog_content = "(Parece que Sharona quiere ir a algún lugar, y quiere viajar solo...)",
  ui_story_30110601_16_dialog_content = "(Su aeronave está averiada, y no puede usar el transporte público o el Otro Extremo...)",
  ui_story_30110601_17_dialog_content = "Um, Comandante Sharona...?",
  ui_story_30110601_18_dialog_content = "M-Tal vez puedo... ¿ayudar?",
  ui_story_30110601_19_dialog_content = "¿No tienes otras cosas que hacer, Caelestite?",
  ui_story_30110601_20_dialog_content = "¿O realmente crees que tu Coloso llama menos la atención que el tren de Charon?",
  ui_story_30110601_21_dialog_content = "Eh... ¿E-Algo así?",
  ui_story_30110601_22_dialog_content = "Al menos Soroz no emite música extraña mientras viaja.",
  ui_story_30110601_23_dialog_content = "...Tienes un punto.",
  ui_story_30110601_24_dialog_content = "En cualquier caso, este es mi propio problema.",
  ui_story_30110601_25_dialog_content = "Pero estás en un verdadero aprieto ahora mismo, ¿no es así?",
  ui_story_30110601_26_dialog_content = "Prometo que no meteré la nariz en tus asuntos personales... Eso es asunto tuyo, no mío.",
  ui_story_30110601_27_dialog_content = "Pero realmente creo que puedo ayudarte con tu dilema de transporte.",
  ui_story_30110601_28_dialog_content = "Eres más que bienvenido a negarte, por supuesto...",
  ui_story_30110601_29_dialog_content = "Al final, es tu decisión. Solo quería darte otra opción.",
  ui_story_30110601_30_dialog_content = "...Bien.",
  ui_story_30110601_31_dialog_content = "Entonces, pongámonos en marcha.",
  ui_story_30110601_32_dialog_content = "¡¿Ya?! ¡Eso fue rápido!",
  ui_story_30110601_33_dialog_content = "¿Qué, ya estás retractándote de tu palabra?",
  ui_story_30110601_34_dialog_content = "¡No estoy!",
  ui_story_30110601_35_dialog_content = "Entonces vamos.",
  ui_story_30110601_36_dialog_content = "¡E-Espérame...!",
  ui_story_30110601_37_dialog_content = "Ahora que lo pienso... Cada año, sin falta, Sharona se viste de esta manera y se va a un lugar no revelado.",
  ui_story_30110601_38_dialog_content = "Me pregunto qué podría significar... ¿Qué divinidad podría estar guiando las acciones del Último de Laden?",
  ui_story_30110601_39_dialog_content = "...¿Hmm? ¿Dónde ha ido la Caelestita?",
  ui_story_30110601_40_dialog_content = "¡Jo-jo! ¡Estoy deseando mucho el espectáculo de hoy!",
  ui_story_30110601_41_dialog_content = "<color=#e8d9bb>Afuera de Umbraton, en un valle aislado...</color>",
  ui_story_30110601_42_dialog_content = "Casi estamos en la ubicación que solicitaste.",
  ui_story_30110601_43_dialog_content = "¿Estás seguro de que este es el lugar correcto, Sharona?",
  ui_story_30110601_44_dialog_content = "Se ve completamente desolado...",
  ui_story_30110601_45_dialog_content = "Este es el lugar correcto.",
  ui_story_30110601_46_dialog_content = "Eh... Parece algo familiar, ahora que lo pienso.",
  ui_story_30110601_47_dialog_content = "Esto es... Esto está justo debajo de Lumopolis, ¿no es así?",
  ui_story_30110601_48_dialog_content = "Sí.",
  ui_story_30110601_49_dialog_content = "Esta área oculta también puede ser utilizada para escapar de una invasión de Eclipsites.",
  ui_story_30110601_50_dialog_content = "Sí... Parece un lugar agradable. Realmente tranquilo y sereno...",
  ui_story_30110601_51_dialog_content = "En su mayoría...",
  ui_story_30110601_52_dialog_content = "Es mejor si te quedas a mi lado, Caelestite.",
  ui_story_30110601_53_dialog_content = "Soy el único que puede garantizar tu seguridad en este lugar.",
  ui_story_30110601_54_dialog_content = "Permanecer a bordo del Colossus es otra opción, pero no necesariamente la mejor.",
  ui_story_30110601_55_dialog_content = "Si alguien lo ve, probablemente atacarán...",
  ui_story_30110601_56_dialog_content = "Así que quédate lo más cerca posible de mí.",
  ui_story_30110601_57_dialog_content = "Cuando lleguemos a nuestro destino, espérame afuera.",
  ui_story_30110601_58_dialog_content = "Yo... No tardaré mucho, lo prometo.",
  ui_story_30110601_59_dialog_content = "Si ves alguna señal de peligro. Llámame y saldré de inmediato.",
  ui_story_30110601_60_dialog_content = "El resto no es asunto tuyo.",
  ui_story_30110601_61_dialog_content = "Ese es el plan para este viaje. ¿Alguna pregunta, Caelestite?",
  ui_story_30110601_62_dialog_content = "...N-No, lo tengo!",
  ui_story_30110601_63_dialog_content = "Bueno. Ahora entonces... Vamos.",
  ui_story_30110601_64_dialog_content = "Muy bien... Estamos aquí.",
  ui_story_30110601_65_dialog_content = "Voy a entrar.",
  ui_story_30110601_66_dialog_content = "Se fue tan rápido...",
  ui_story_30110601_67_dialog_content = "Ahora que estoy solo, este lugar se siente un poco espeluznante.",
  ui_story_30110601_68_dialog_content = "Es frío...",
  ui_story_30110601_69_dialog_content = "La vegetación aquí es tan densa.",
  ui_story_30110601_70_dialog_content = "Está tranquilo... Demasiado tranquilo. Es casi insoportable...",
  ui_story_30110601_71_dialog_content = "Creo que me pararé más cerca de la entrada...",
  ui_story_30110601_72_dialog_content = "¡Graaagh!",
  ui_story_30110601_73_dialog_content = "Así que también han encontrado su camino a este lugar...",
  ui_story_30110601_74_dialog_content = "¡¡¡Graaaagh!!!",
  ui_story_30110601_75_dialog_content = "¡Cómo te atreves a sembrar el caos aquí!",
  ui_story_30110601_76_dialog_content = "¡Oh no, es eso... el olor de los Eclipsites?!",
  ui_story_30110601_77_dialog_content = "Hay sonidos de lucha provenientes del interior...",
  ui_story_30110601_78_dialog_content = "¡Sharona está allí completamente sola! ¡Tengo que ir a ayudarla!",
  ui_story_30110601_79_dialog_content = "¿Este lugar... es un cementerio?",
  ui_story_30110601_80_dialog_content = "Es extrañamente tranquilo ahora... ¿La batalla ya ha terminado?",
  ui_story_30110601_81_dialog_content = "Sharona! Sharona!!",
  ui_story_30110601_82_dialog_content = "¡Si puedes oírme, por favor di algo!",
  ui_story_30110601_83_dialog_content = "Sharo—",
  ui_story_30110601_84_dialog_content = "Estoy aquí, Caelestita.",
  ui_story_30110601_85_dialog_content = "Whoa...",
  ui_story_30110601_86_dialog_content = "¿Qué es este lugar, Sharona? ¿Son esos...?",
  ui_story_30110601_87_dialog_content = "...",
  ui_story_30110601_88_dialog_content = "Nada digno de mención. Estos son murales, nada más.",
  ui_story_30110601_89_dialog_content = "Son hermosos... no, ¡impactantes!",
  ui_story_30110601_90_dialog_content = "No puedo explicarlo, pero estoy empezando a tener la piel de gallina.",
  ui_story_30110601_91_dialog_content = "¿Estás herida?",
  ui_story_30110601_92_dialog_content = "No.",
  ui_story_30110601_93_dialog_content = "Eso es bueno.",
  ui_story_30110601_94_dialog_content = "Sharona... ¿Qué es este lugar?",
  ui_story_30110601_95_dialog_content = "Las personas en estos murales... Sus ropas parecen un poco familiares.",
  ui_story_30110601_96_dialog_content = "Lo hacen, ¿no es así?",
  ui_story_30110601_97_dialog_content = "Son de Lumopolis.",
  ui_story_30110601_98_dialog_content = "¡¿Lumopolis?! Pero ¿no siempre has estado...",
  ui_story_30110601_99_dialog_content = "¿Contra las viejas y obstinadas costumbres de Lumopolis?",
  ui_story_30110601_100_dialog_content = "Si es así, ¿por qué elegirías venir aquí? Este lugar... si no me equivoco, es un cementerio para la nobleza de Lumopolis.",
  ui_story_30110601_101_dialog_content = "...",
  ui_story_30110601_102_dialog_content = "Honestamente pensé que ya habrías usado tus poderos para descubrir la verdad, Caelestite.",
  ui_story_30110601_103_dialog_content = "Este es el lugar de descanso final de <color=#FFB400>mis clan</color>.",
  ui_story_30110601_104_dialog_content = "La tierra bajo tus pies está fertilizada por la sangre y los huesos de la noble Familia <color=#FFB400>Kartima</color>.",
  ui_story_30110601_105_dialog_content = "Deberían haber sido puestos a descansar en el reino celestial de la Noche Blanca en lo alto...",
  ui_story_30110601_106_dialog_content = "Pero desafortunadamente, debido al incidente...",
  ui_story_30110601_107_dialog_content = "Una lucha de poder que carecía de documentación adecuada y estaba plagada de registros falsos.",
  ui_story_30110601_108_dialog_content = "La Familia Kartima ha sido marcada como traidores desde entonces.",
  ui_story_30110601_109_dialog_content = "Los miembros vivos fueron exiliados, y los difuntos ni siquiera podían descansar en paz.",
  ui_story_30110601_110_dialog_content = "Ni siquiera se les concedió la misericordia de ser enterrados en su propio cementerio. Todo lo que podían hacer era implorar a las familias más compasivas que les ayudaran en secreto...",
  ui_story_30110601_111_dialog_content = "...Y así, fueron enterrados aquí.",
  ui_story_30110601_112_dialog_content = "Qué irónico...",
  ui_story_30110601_113_dialog_content = "Los antepasados de la Familia Kartima sacrificaron su sangre y vidas para proteger a Lumopolis, pero ahora... Han sido prácticamente olvidados por la gente.",
  ui_story_30110601_114_dialog_content = "El imperio ha olvidado que su gloria actual fue construida sobre la sangre de los dragones.",
  ui_story_30110601_115_dialog_content = "La Noche Blanca en lo alto...",
  ui_story_30110601_116_dialog_content = "Pero sangre y huesos debajo.",
  ui_story_30110601_117_dialog_content = "Lo siento mucho.",
  ui_story_30110601_118_dialog_content = "No quise entrometerme...",
  ui_story_30110601_119_dialog_content = "Por favor acepta mis disculpas, Sharona... Tú y tu familia.",
  ui_story_30110601_120_dialog_content = "Como forastero, he perturbado su sueño.",
  ui_story_30110601_121_dialog_content = "...",
  ui_story_30110601_122_dialog_content = "Ellos no son mi familia.",
  ui_story_30110601_123_dialog_content = "Pero tu nombre...",
  ui_story_30110601_124_dialog_content = "¿Realmente crees que somos una familia solo porque compartimos un apellido?",
  ui_story_30110601_125_dialog_content = "Sharona Kartima...",
  ui_story_30110601_126_dialog_content = "Ellos son mis clan, pero no son mi familia.",
  ui_story_30110601_127_dialog_content = "No tienen forma de decirme la verdad sobre la muerte de mis padres, y tampoco puedo fingir que no estoy conectado con ellos de alguna manera.",
  ui_story_30110601_128_dialog_content = "Tus padres...",
  ui_story_30110601_129_dialog_content = "Ya ni siquiera los recuerdo.",
  ui_story_30110601_130_dialog_content = "Cuando se trata de la Familia Kartima, lo que me dejó la impresión más profunda...",
  ui_story_30110601_131_dialog_content = "Ocurrió el día del <color=#FFB400>genocidio</color>.",
  ui_story_30110601_132_dialog_content = "Justo antes de morir, un anciano muy respetado en la familia me dijo...",
  ui_story_30110601_133_dialog_content = "Para siempre recordar mi nombre, y nunca abandonar la búsqueda del <color=#FFB400>secreto</color> de mi linaje.",
  ui_story_30110601_134_dialog_content = "Antes de eso, ni siquiera merecía saludar al hombre en las reuniones familiares.",
  ui_story_30110601_135_dialog_content = "Entonces... ¿ya has descubierto el secreto de tu linaje?",
  ui_story_30110601_136_dialog_content = "He buscado durante mucho, mucho tiempo, pero... aún no he encontrado la respuesta.",
  ui_story_30110601_137_dialog_content = "Ni siquiera sé por qué me confiaron esta tarea imposible en primer lugar.",
  ui_story_30110601_138_dialog_content = "Solo porque soy el último miembro sobreviviente de nuestra familia, ¿se espera que cargue con el peso de la historia secreta de nuestra línea de sangre?",
  ui_story_30110601_139_dialog_content = "Fragmentos del pasado surgen constantemente en mi mente, trayendo un flujo interminable de odio...",
  ui_story_30110601_140_dialog_content = "...Esto no es justo.",
  ui_story_30110601_141_dialog_content = "Lo siento...",
  ui_story_30110601_142_dialog_content = "Realmente no quise preguntar sobre ti y el pasado de tu clan...",
  ui_story_30110601_143_dialog_content = "Si no me hubieras traído aquí, nunca lo habrías sabido.",
  ui_story_30110601_144_dialog_content = "Sí...",
  ui_story_30110601_145_dialog_content = "¡Espera... Familia! ¡Así es!",
  ui_story_30110601_146_dialog_content = "¡Illumina! ¡La Federación Illumina!",
  ui_story_30110601_147_option_content = "Son tu verdadero hogar, ¿verdad, Sharona?",
  ui_story_30110601_148_dialog_content = "...¿Mi hogar?",
  ui_story_30110601_149_dialog_content = "El hogar es un lugar que me ama incondicionalmente y no pide nada a cambio.",
  ui_story_30110601_150_dialog_content = "Mi relación con Illumina... Se construyó sobre la confianza del Gran Mariscal.",
  ui_story_30110601_151_option_content = "No, Illumina tampoco cuenta...",
  ui_story_30110601_152_dialog_content = "Estoy de acuerdo, en su mayoría.",
  ui_story_30110601_153_dialog_content = "El significado de hogar es mucho más profundo.",
  ui_story_30110601_154_dialog_content = "Un hogar proporciona un sentido profundo e inseparable de amor...",
  ui_story_30110601_155_dialog_content = "Mientras que en Illumina, trabajo solo para estar a la altura de la confianza y las expectativas de los demás.",
  ui_story_30110601_156_dialog_content = "Aunque, a cambio, se me ha concedido un poder considerable...",
  ui_story_30110601_157_dialog_content = "A veces, me encuentro diciendo... Que tal vez este lugar es mi hogar.",
  ui_story_30110601_158_dialog_content = "(¿Qué significa realmente hogar...?)",
  ui_story_30110601_159_dialog_content = "(Nunca he vivido en Eraveil yo mismo, pero...)",
  ui_story_30110601_160_dialog_content = "(Puedo decir, con total certeza, que Eraveil es mi hogar.)",
  ui_story_30110601_161_dialog_content = "(Y Soroz... No es solo mi refugio, sino también mi amigo. Nunca estuve realmente solo mientras crecía...)",
  ui_story_30110601_162_dialog_content = "(Y he hecho todo tipo de amigos desde entonces.)",
  ui_story_30110601_163_dialog_content = "(Pero a Sharona... ¿Dónde sería su hogar para ella?)",
  ui_story_30110601_164_dialog_content = "(Nunca llegué a conocer a ninguno de mis parientes, pero estoy seguro de que su amor por mí era real.)",
  ui_story_30110601_165_dialog_content = "(Sharona creció rodeado de familia, pero aún no sabe dónde está su hogar...)",
  ui_story_30110601_166_dialog_content = "He dicho demasiado.",
  ui_story_30110601_167_dialog_content = "Gracias por tu ayuda, Caelestite.",
  ui_story_30110601_168_dialog_content = "N-No lo menciones.",
  ui_story_30110601_169_dialog_content = "Estoy seguro de que todo esto debe ser confuso para ti.",
  ui_story_30110601_170_dialog_content = "Después de todo, ¿por qué estaría aquí presentando mis respetos si no son mi familia?",
  ui_story_30110601_171_dialog_content = "Creo... Estás tratando de llegar al fondo de lo que sucedió en el pasado, ¿verdad?",
  ui_story_30110601_172_option_content = "¿La verdad detrás de tu clan?",
  ui_story_30110601_173_dialog_content = "Sí.",
  ui_story_30110601_174_dialog_content = "Así como nuestra conexión con los dragones.",
  ui_story_30110601_175_dialog_content = "Los fragmentos gritantes de mis recuerdos... de verdaderos dragones.",
  ui_story_30110601_176_option_content = "¿El secreto de tu linaje?",
  ui_story_30110601_177_dialog_content = "Sí.",
  ui_story_30110601_178_dialog_content = "Quizás después de descubrir los secretos de la Familia Kartima...",
  ui_story_30110601_179_dialog_content = "La verdad detrás del pasado, y la respuesta a los fragmentos de odio en mi mente... Tal vez todo se revele entonces.",
  ui_story_30110601_180_dialog_content = "Pero hasta que descubra la verdad detrás de todo...",
  ui_story_30110601_181_dialog_content = "Todo lo que puedo hacer es venir aquí a presentar mis respetos cada año, con la esperanza de sentir algo...",
  ui_story_30110601_182_dialog_content = "Porque compartimos un apellido, nunca estoy realmente solo.",
  ui_story_30110601_183_dialog_content = "Incluso si... No los considero mi familia.",
  ui_story_30110601_184_dialog_content = "(Familia...)",
  ui_story_30110601_185_dialog_content = "Yo...",
  ui_story_30110601_186_dialog_content = "Sharona... Por favor, ofrezca mis respetos en mi lugar.",
  ui_story_30110601_187_dialog_content = "Vamos.",
  ui_story_30110601_188_dialog_content = "Antes de irnos... Hay algo que debo preguntarte.",
  ui_story_30110601_189_dialog_content = "Seguro.",
  ui_story_30110601_190_dialog_content = "Caelestite... Te pido que te abstengas de revelar la ubicación de este lugar a cualquier otra persona.",
  ui_story_30110601_191_dialog_content = "En lo que respecta a mi comprensión de la gente de Lumopolis...",
  ui_story_30110601_192_dialog_content = "Son rápidos para olvidar la amabilidad, pero nunca olvidarán un rencor.",
  ui_story_30110601_193_dialog_content = "Especialmente no un rencor contra la traicionera Familia Kartima...",
  ui_story_30110601_194_dialog_content = "Su odio nunca desaparecerá realmente.",
  ui_story_30110601_195_dialog_content = "Esto, me temo, es lo único que tengo en común con la gente de Lumopolis.",
  ui_story_30110601_196_dialog_content = "Siempre está ahí... Esa familiar sensación de odio, haciendo que mi sangre hierva constantemente...",
  ui_story_30110601_197_dialog_content = "Lo prometo.",
  ui_story_30110601_198_dialog_content = "Qué momento tan conmovedor...",
  ui_story_30110601_199_dialog_content = "Si realmente fuera tan conmovedor, ¿por qué no estás llorando?",
  ui_story_30110601_200_dialog_content = "¿Llorar? ¿Por qué iba a llorar?",
  ui_story_30110601_201_dialog_content = "No me hagas reír.",
  ui_story_30110601_202_dialog_content = "...Llegas tarde, Leona.",
  ui_story_30110601_203_dialog_content = "¿Tarde? No son dignos de mi visita, y mucho menos de mi puntualidad.",
  ui_story_30110601_204_dialog_content = "Ese traje tuyo...",
  ui_story_30110601_205_dialog_content = "¿Todavía intentas seguir sus <color=#FFB400>tradiciones</color> largamente muertas, Sharona?",
  ui_story_30110601_206_dialog_content = "Nadie en el mundo aparte de mí reconoce ese atuendo como el traje formal de la Familia Kartima.",
  ui_story_30110601_207_dialog_content = "Entonces, mientras estemos vivos, y yo tenga este atuendo...",
  ui_story_30110601_208_dialog_content = "La Familia Kartima no ha sido completamente abandonada por la historia.",
  ui_story_30110601_209_dialog_content = "Hmph... Qué ingenuo.",
  ui_story_30110601_210_dialog_content = "¿Cuál es el punto de estas formalidades y tributos, si estamos condenados a repetir los mismos errores?",
  ui_story_30110601_211_dialog_content = "Pero eso ya lo sabes perfectamente bien, ¿no es así... hermanita?",
  ui_story_30110601_212_dialog_content = "No hay escapatoria a este destino. Algún día, también estaremos yaciendo fríos y muertos en este lugar.",
  ui_story_30110601_213_dialog_content = "La única diferencia es que, cuando nos vayamos, nadie estará allí para vestir esas ropas y rendirnos homenaje.",
  ui_story_30110601_214_dialog_content = "...No importa.",
  ui_story_30110601_215_dialog_content = "Oh, querida hermana... tu comprensión del destino es tan lamentablemente superficial.",
  ui_story_30110601_216_dialog_content = "Pero creo...",
  ui_story_30110601_217_dialog_content = "Hay alguien aquí con una comprensión mucho más profunda de la palabra destino...",
  ui_story_30110601_218_dialog_content = "¿No es así... La solitaria Caelestita?",
  ui_story_30110601_219_dialog_content = "...¿Yo?",
  ui_story_30110601_220_dialog_content = "¡No estoy solo en absoluto!",
  ui_story_30110601_221_dialog_content = "¿Es así, kiddo? Envidio tu confianza.",
  ui_story_30110601_222_dialog_content = "Solo espero que nunca dejes de sentirte así...",
  ui_story_30110601_223_dialog_content = "Ahora, mis dulzuras. Tengo que decir adiós.",
  ui_story_30110601_224_dialog_content = "Ella entró, Sharona...",
  ui_story_30110601_225_dialog_content = "...",
  ui_story_30110601_226_dialog_content = "¿Sharona? ¡Sharona!",
  ui_story_30110601_227_dialog_content = "...Vamos.",
  ui_story_30110601_228_dialog_content = "De vuelta a... Illumina.",
  ui_story_30110601_229_dialog_content = "...Seguro. Regresemos juntos.",
  ui_story_30110601_230_dialog_content = "<color=#e8d9bb>El día siguiente.</color>",
  ui_story_30110601_231_dialog_content = "¿Navegante? ¡Oye, Navegante! ¿Te sientes bien?",
  ui_story_30110601_232_dialog_content = "Eh... ¿Eh?",
  ui_story_30110601_233_dialog_content = "¿Qué tienes en mente? ¿Necesitas un poco de aire fresco? ¡Vamos, demos un paseo por la ciudad de Gannon!",
  ui_story_30110601_234_dialog_content = "N-Nada en mi mente, de verdad...",
  ui_story_30110601_235_dialog_content = "Oye, Vice... ¿qué significa para ti la palabra hogar?",
  ui_story_30110601_236_dialog_content = "¿Eh? Si tuviera que decir...",
  ui_story_30110601_237_dialog_content = "El Coloso es mi hogar, y también lo es Illumina.",
  ui_story_30110601_238_dialog_content = "Cualquier lugar donde pueda vivir cómodamente es un lugar al que puedo llamar hogar.",
  ui_story_30110601_239_dialog_content = "Sí...",
  ui_story_30110601_240_dialog_content = "Un lugar cómodo...",
  ui_story_30110601_241_dialog_content = "(Para Sharona, el hogar es un lugar al que siempre puede regresar. Es donde ella pertenece.",
  ui_story_30110601_242_dialog_content = "(Dedicándose a Illumina...)",
  ui_story_30110601_243_dialog_content = "(Es su forma de resistir al destino y encontrar un hogar.)",
  ui_story_30110601_244_dialog_content = "(Solo me pregunto...)",
  ui_story_30110601_245_dialog_content = "(¿Si el Coloso alguna vez se sentirá como su hogar?)",
  ui_story_30110602_1_dialog_content = "Según las coordenadas, este debería ser el lugar. Pero...",
  ui_story_30110602_2_dialog_content = "¿Realmente Sharona está llegando tarde?",
  ui_story_30110602_3_dialog_content = "Incluso si ese es el caso, la mayoría de las tropas de Illumina deberían estar aquí ya...",
  ui_story_30110602_4_dialog_content = "No debería estar tan tranquilo por aquí.",
  ui_story_30110602_5_dialog_content = "¿Podría ser... ¿Me equivoqué de ubicación?",
  ui_story_30110602_6_dialog_content = "Si llego tarde por una estupidez como esa, Sharona se va a enfurecer. Será mejor que...",
  ui_story_30110602_7_dialog_content = "No, estás en el lugar correcto, PlayerName.",
  ui_story_30110602_8_dialog_content = "!",
  ui_story_30110602_9_dialog_content = "¿Comandante Sharona? ¡Casi no te reconocí! Así que estuviste aquí todo el tiempo...",
  ui_story_30110602_10_dialog_content = "Tú, uh...",
  ui_story_30110602_11_dialog_content = "Deja de andarte por las ramas. Si tienes preguntas, simplemente pregúntame ya.",
  ui_story_30110602_12_dialog_content = "¿Por qué estás completamente solo? ¿Dónde está el resto de la Legión de Illumina? Y... ¿Qué pasa con esa ropa?",
  ui_story_30110602_13_dialog_content = "Responderé tus preguntas una a la vez.",
  ui_story_30110602_14_dialog_content = "Primero, esta es una misión privada, una que no involucra al ejército de la Federación Illumina.",
  ui_story_30110602_15_dialog_content = "En segundo lugar, preparé estas ropas específicamente para esta misión.",
  ui_story_30110602_16_dialog_content = "Ropa especial para una misión privada, ¿eh? Bueno, sí se ven increíblemente caras.",
  ui_story_30110602_17_dialog_content = "De hecho, parecen un poco fuera de lugar aquí.",
  ui_story_30110602_18_dialog_content = "¿Tienen algo que ver con estas ruinas blancas?",
  ui_story_30110602_19_dialog_content = "Muy perceptivo, PlayerName.",
  ui_story_30110602_20_dialog_content = "Recientemente me topé con un grupo de personas de aspecto sospechoso. Regularmente adoran a un ídolo de dragón cercano.",
  ui_story_30110602_21_dialog_content = "Supongo que probablemente son un grupo de malvados sectarios... o los restos de una facción traidora.",
  ui_story_30110602_22_dialog_content = "¿Eso significa...?",
  ui_story_30110602_23_dialog_content = "Sospecho que están conectados con la Casa Kartima de alguna manera, sí.",
  ui_story_30110602_24_dialog_content = "¿Así que estas ropas pertenecen a la Casa Kartima?",
  ui_story_30110602_25_dialog_content = "Para nada. Esto es simplemente un disfraz utilizado para infiltrarse en sus filas.",
  ui_story_30110602_26_dialog_content = "Elegí estas ropas para que combinen con las que vi que llevaban durante su adoración.",
  ui_story_30110602_27_dialog_content = "¿En serio? Pero parece que estuvieran hechos a medida solo para ti.",
  ui_story_30110602_28_dialog_content = "Con un atuendo tan puro y digno como este, incluso podrían pensar que eres un santo o algo así.",
  ui_story_30110602_29_dialog_content = "Eso no es importante ahora, PlayerName.",
  ui_story_30110602_30_dialog_content = "Lo único que importa es que pude usar este disfraz para infiltrarme y derrotarlos.",
  ui_story_30110602_31_dialog_content = "La escena ya ha sido despejada de cualquier signo de batalla, por eso te invité aquí.",
  ui_story_30110602_32_dialog_content = "Alguien tan versado en historia antigua como tú debería poder decir si estas ruinas están vinculadas a la Casa Kartima o a los dragones, ¿verdad?",
  ui_story_30110602_33_dialog_content = "Ciertamente intentaré hacer lo mejor que pueda.",
  ui_story_30110602_34_dialog_content = "Pero... ¿No sería más fácil simplemente preguntar a las personas que detuviste?",
  ui_story_30110602_35_dialog_content = "... Lo intenté, pero solo uno de ellos seguía consciente después de la batalla, y se desmayó tan pronto como comencé a interrogarlo.",
  ui_story_30110602_36_dialog_content = "No es sorprendente en absoluto... Casi puedo visualizar la batalla en mi mente...",
  ui_story_30110602_37_dialog_content = "Además, seguían diciendo tonterías durante nuestra pelea. Algo me decía que no obtendría nada útil de ellos en mucho tiempo.",
  ui_story_30110602_38_dialog_content = "Por lo cual decidí pedir tu ayuda.",
  ui_story_30110602_39_dialog_content = "Entiendo. No te preocupes, tengo esto.",
  ui_story_30110602_40_dialog_content = "<color=#e8d9bb>Después de un rato...</color>",
  ui_story_30110602_41_dialog_content = "Uf... Creo que ya he descubierto la mayoría de ello ahora.",
  ui_story_30110602_42_dialog_content = "La respuesta podría ser un poco decepcionante. Este lugar no tiene nada que ver con la Casa Kartima.",
  ui_story_30110602_43_dialog_content = "... ¿Es eso así?",
  ui_story_30110602_44_dialog_content = "Entonces, ¿por qué estarían adorando aquí?",
  ui_story_30110602_45_dialog_content = "Parecen estar orando a un poder superior maligno. Juzgando por las evidencias que hay por aquí...",
  ui_story_30110602_46_dialog_content = "Es posible que vean al ídolo del dragón como una especie de Eclipsita poderoso.",
  ui_story_30110602_47_dialog_content = "Después de todo, no hay muchas personas que hayan visto un dragón real en estos días.",
  ui_story_30110602_48_dialog_content = "Entiendo. Debería haber sabido que no debía hacerme ilusiones.",
  ui_story_30110602_49_dialog_content = "El hombre del que hablé antes, el que se desmayó de miedo durante mi interrogatorio... Había una razón para eso.",
  ui_story_30110602_50_dialog_content = "Durante nuestra batalla de antes...",
  ui_story_30110602_51_dialog_content = "¿Qué paso?",
  ui_story_30110602_52_dialog_content = "Me emocioné demasiado y casi perdí mi sentido de la razón.",
  ui_story_30110602_53_dialog_content = "La posibilidad de que tuvieran vínculos con mi familia y la rebelión hizo que me fuera imposible controlar mis emociones.",
  ui_story_30110602_54_dialog_content = "Sus gritos estaban llenos de terror mientras intentaban desesperadamente mantenerme alejado...",
  ui_story_30110602_55_dialog_content = "Honestamente, detesto esa parte de mí mismo.",
  ui_story_30110602_56_dialog_content = "Pero recuperaste el control al final, ¿no es así?",
  ui_story_30110602_57_dialog_content = "Lo hice, pero solo a regañadientes. La verdad es—",
  ui_story_30110602_58_dialog_content = "Solo recuperé el control porque pensé que podrías darme más respuestas, PlayerName.",
  ui_story_30110602_59_dialog_content = "Pero mi odio hacia Lumopolis y mi familia... así como mi propio poder—",
  ui_story_30110602_60_dialog_content = "Podría llegar un día en que me haga perder completamente el control.",
  ui_story_30110602_61_dialog_content = "Es posible que mi alma haya cedido hace mucho tiempo a la violencia.",
  ui_story_30110602_62_dialog_content = "Si tan solo pudiera saber qué pensaban mis antepasados sobre este poder.",
  ui_story_30110602_63_dialog_content = "(Así que por eso quería saber si estas ruinas tenían algo que ver con su familia...)",
  ui_story_30110602_64_dialog_content = "Bueno... Por lo que pude entender, realmente lograste derribar a un grupo de malvados cultistas.",
  ui_story_30110602_65_dialog_content = "Si no los hubieras detenido, quién sabe qué tipo de problemas habrían causado.",
  ui_story_30110602_66_dialog_content = "Esa es una gran victoria en mi libro. ¿No estás de acuerdo?",
  ui_story_30110602_67_dialog_content = "Pero solo lo hice por puro interés propio.",
  ui_story_30110602_68_dialog_content = "Yo no iría tan lejos, Sharona.",
  ui_story_30110602_69_dialog_content = "Si realmente solo estabas interesado en aprender sobre sus lazos con la Casa Kartima, podrías haber evitado fácilmente pelear con ellos.",
  ui_story_30110602_70_dialog_content = "Pero viste a su grupo como una amenaza para Illumina y los demás, así que actuaste de manera decisiva y los derribaste.",
  ui_story_30110602_71_dialog_content = "Al final del día, aún quieres usar tu poder para proteger a los demás, ¿verdad?",
  ui_story_30110602_72_dialog_content = "Pero... ¿Realmente se puede usar un poder destructivo como el mío para proteger a las personas?",
  ui_story_30110602_73_dialog_content = "¡Puede! El hecho de que la Casa Kartima haya existido después de todo este tiempo es prueba de eso.",
  ui_story_30110602_74_dialog_content = "Estoy seguro de que tus ancestros también usaron su poder para proteger a los que les importaban en su día.",
  ui_story_30110602_75_dialog_content = "También estoy seguro de que has heredado su deber y usarás tu propio poder para proteger a Illumina y a las personas que te importan.",
  ui_story_30110602_76_dialog_content = "¿Realmente tengo el derecho de hacer eso?",
  ui_story_30110602_77_dialog_content = "Por supuesto que sí, Sharona! He visto lo fuerte que eres, pero también he visto lo amable que puedes ser.",
  ui_story_30110602_78_dialog_content = "Si alguien puede hacer esto, ¡eres tú!",
  ui_story_30110602_79_dialog_content = "...",
  ui_story_30110602_80_dialog_content = "Gracias, PlayerName. Siempre he estado agradecido por tu orientación interminable.",
  ui_story_30110602_81_dialog_content = "A veces me pregunto cómo sería mi vida si tuviera a alguien como tú en mi familia.",
  ui_story_30110602_82_dialog_content = "¿Me convertiría en este salvaje si ese fuera el caso?",
  ui_story_30110602_83_dialog_content = "Familia...",
  ui_story_30110602_84_dialog_content = "(Sharona mencionó algo sobre esto antes...)",
  ui_story_30110602_85_dialog_content = "El hogar es un lugar que me ama incondicionalmente y no pide nada a cambio.",
  ui_story_30110602_86_dialog_content = "(Si ella realmente no ve a Illumina como un lugar al que pueda llamar hogar, entonces...)",
  ui_story_30110602_87_option_content = "¿Por qué no haces del Coloso tu hogar?",
  ui_story_30110602_88_dialog_content = "¿El Coloso? Bueno, sí tiene una cierta sensación de hogar.",
  ui_story_30110602_89_dialog_content = "Tú y tus amigos viven allí, y todos parecen verlo como un lugar donde siempre son bienvenidos.",
  ui_story_30110602_90_dialog_content = "Pero... Por favor perdona mi indiscreción y olvida cualquier cosa que dije sobre el asunto.",
  ui_story_30110602_91_option_content = "¿Quieres que sea parte de tu familia?",
  ui_story_30110602_92_dialog_content = "Ah... lo siento, PlayerName, solo estaba hablando conmigo mismo hace un momento.",
  ui_story_30110602_93_dialog_content = "Por favor, perdóname por expresar esos pensamientos sin sentido y hacerte preocupar.",
  ui_story_30110602_94_dialog_content = "Intenta no pensar demasiado en ello. No fue más que una queja casual.",
  ui_story_30110602_95_dialog_content = "Estaba hablando en serio.",
  ui_story_30110602_96_dialog_content = "¿Eras tú?",
  ui_story_30110602_97_dialog_content = "Por supuesto. No me atrevería a hacer bromas delante de un ídolo de dragón, después de todo.",
  ui_story_30110602_98_dialog_content = "Una vez me dijiste que Illumina realmente no era tu hogar... Si alguna vez estás interesado, ¡creo que el Coloso es una gran elección!",
  ui_story_30110602_99_dialog_content = "Siempre estás cuidando de mí, así que quiero hacer todo lo posible para ayudarte también.",
  ui_story_30110602_100_dialog_content = "Puede que sea un poco arrogante de mi parte decirlo, pero realmente espero poder convertirme en alguien en quien puedas confiar.",
  ui_story_30110602_101_dialog_content = "Después de todo, dijiste que pensaste en mí justo antes de que perdieras el control antes, ¿verdad?",
  ui_story_30110602_102_dialog_content = "Si pensar en mí te ayuda, entonces tal vez algún día podrás transformar tu poder destructivo—",
  ui_story_30110602_103_dialog_content = "—¿en el poder para proteger algo importante?",
  ui_story_30110602_104_dialog_content = "Algo importante...",
  ui_story_30110602_105_dialog_content = "No puedo negar que cruzaste mi mente más temprano, PlayerName.",
  ui_story_30110602_106_dialog_content = "Pero...",
  ui_story_30110602_107_dialog_content = "¡Ah, pero no tienes que tomar una decisión ahora mismo o algo así!",
  ui_story_30110602_108_dialog_content = "Aunque sea atrevido de mi parte preguntar, realmente espero que lo tomes en consideración, Sharona.",
  ui_story_30110602_109_dialog_content = "Por favor, no malinterpretes, no estaba tratando de molestarte.",
  ui_story_30110602_110_dialog_content = "Pero la idea de que te conviertas en parte de mi familia...",
  ui_story_30110602_111_dialog_content = "No estoy seguro de que pueda aceptar eso... no como estoy ahora, de todos modos.",
  ui_story_30110602_112_dialog_content = "Podría necesitar más tiempo para prepararme.",
  ui_story_30110602_113_dialog_content = "¡Toma todo el tiempo que necesites! Cuando tengas tiempo libre, ¿por qué no vienes a visitar tu posible nuevo hogar?",
  ui_story_30110602_114_dialog_content = "Siempre estoy abierto a sugerencias, especialmente si hacen que el Coloso se sienta más como tu hogar.",
  ui_story_30110602_115_dialog_content = "Eso no será necesario.",
  ui_story_30110602_116_dialog_content = "No me hace ninguna diferencia si estoy en Illumina o a bordo del Coloso.",
  ui_story_30110602_117_dialog_content = "<size=30>Mientras esté a tu lado...</size>",
  ui_story_30110602_118_dialog_content = "¿Qué fue eso?",
  ui_story_30110602_119_dialog_content = "Oh, nada. Solo estaba... hablando conmigo mismo otra vez.",
  ui_story_30110602_120_dialog_content = "Resulta que tengo algo de tiempo libre hoy, ya que tomé el día libre para esta misión privada.",
